script:
// Independently implemented public JSON protocol; no upstream code copied.
// Protocol reference: keiyoushi/extensions-source TerraHistoricus at
// dbf6c05d6a9520c60533f1626616263522bbe71a (Apache-2.0).
// Signed image URLs are resolved afresh on every content call. The host has
// no image-403 interceptor: reopen/reload the chapter after a URL expires.
var TH_BASE = 'https://comic.hypergryph.com';
var TH_TOPICS = ['terra-historicus', 'talos-ii-historicus'];
var thSequence = 0;
function thFail(message) { throw new Error('泰拉记事社：' + message); }
function thObject(value, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) thFail(label + '格式无效');
  return value;
}
function thList(value, label, limit) {
  if (!Array.isArray(value) || value.length > limit) thFail(label + '格式无效或超出安全上限');
  return value;
}
function thText(value, label) {
  if (typeof value !== 'string' || !value.trim() || value.length > 4096) thFail(label + '缺失或格式无效');
  return value.trim();
}
function thId(value) {
  if (typeof value !== 'string' || !/^[A-Za-z0-9_-]{1,80}$/.test(value)) thFail('作品或章节编号无效');
  return value;
}
function thImage(value) {
  if (typeof value !== 'string' || value.length > 8192 || !/^https:\/\/(?:[a-z0-9-]+\.)*(?:hycdn\.cn|hypergryph\.com)\//i.test(value) || /[\s\\#]/.test(value))
    thFail('图片地址无效；仅接受官方 HTTPS 图片');
  return value;
}
async function thFetch(path, fresh) {
  var response = await triomi.fetch(TH_BASE + path, fresh ? {headers: {'Cache-Control': 'no-cache'}} : {});
  if (response.status === 401 || response.status === 402 || response.status === 403)
    thFail('访问受限（HTTP ' + response.status + '）；请在官网检查登录、授权或访问验证，规则不会绕过限制');
  if (response.status !== 200) thFail('官网请求失败（HTTP ' + response.status + '）');
  if (typeof response.body !== 'string' || response.body.length > 4000000) thFail('官网响应过大或格式无效');
  var result;
  try { result = JSON.parse(response.body); } catch (_) { thFail('官网返回非 JSON 内容，可能需要访问验证，请在官网查看'); }
  thObject(result, '官网响应');
  if (result.code !== 0) {
    var message = typeof result.msg === 'string' ? result.msg.replace(/<[^>]*>/g, '').slice(0, 160) : '';
    thFail('官网拒绝请求（code ' + String(result.code).slice(0, 20) + '）' + (message ? '：' + message : '；请在官网查看访问权限'));
  }
  if (result.data == null) thFail('官网响应缺少 data');
  return result.data;
}
function thItem(row, topic, recent) {
  thObject(row, '作品');
  var cid = thId(recent ? row.comicCid : row.cid);
  var tags = [];
  if (row.type === 2) tags.push('相簿');
  if (row.type === 3) tags.push('四格');
  if (row.keywords != null) thList(row.keywords, '关键词', 100).forEach(function (tag) { tags.push(thText(tag, '关键词')); });
  var description = [];
  if (typeof row.subtitle === 'string' && row.subtitle.trim()) description.push('「' + row.subtitle.trim() + '」');
  if (typeof row.introduction === 'string' && row.introduction.trim()) description.push(row.introduction.trim());
  var authors = row.authors == null ? [] : thList(row.authors, '作者', 100).map(function (name) { return thText(name, '作者'); });
  return {remoteId: topic + '/' + cid, type: 'manga', title: thText(row.title, '作品标题'),
    url: TH_BASE + '/' + topic + '/comic/' + cid, coverUrl: thImage(recent ? row.coverUrl : row.cover),
    author: authors.join('、'), description: description.join('\n'), tags: tags};
}
async function thCatalog(topic, recent) {
  var data = await thFetch('/api/' + (recent ? 'recentUpdate' : 'comic') + '?topicKey=' + topic);
  var seen = {};
  var items = [];
  thList(data, '作品列表', 1000).forEach(function (row) {
    var item = thItem(row, topic, recent);
    if (!seen[item.remoteId]) { seen[item.remoteId] = true; items.push(item); }
  });
  return items;
}
function thPage(page) {
  if (!Number.isInteger(page) || page < 1) thFail('页码无效');
  return page;
}
async function discover(url, page) {
  if (thPage(page) !== 1) return [];
  var match = /^https:\/\/comic\.hypergryph\.com\/api\/(comic|recentUpdate)\?topicKey=(terra-historicus|talos-ii-historicus)$/.exec(url);
  if (!match) thFail('发现页地址无效');
  return thCatalog(match[2], match[1] === 'recentUpdate');
}
async function search(keyword, page) {
  if (thPage(page) !== 1) return [];
  if (typeof keyword !== 'string' || keyword.length > 200) thFail('搜索词无效');
  var query = keyword.trim().toLowerCase();
  var result = [];
  for (var i = 0; i < TH_TOPICS.length; i++) {
    var rows = await thCatalog(TH_TOPICS[i], false);
    rows.forEach(function (item) { if (item.title.toLowerCase().indexOf(query) !== -1) result.push(item); });
  }
  return result;
}
function thLocation(url, chapter) {
  var match = /^https:\/\/comic\.hypergryph\.com\/(terra-historicus|talos-ii-historicus)\/comic\/([A-Za-z0-9_-]{1,80})(?:\/episode\/([A-Za-z0-9_-]{1,80}))?\/?$/.exec(url || '');
  if (!match || (chapter ? !match[3] : !!match[3])) thFail('作品或章节地址无效；请从对应主题重新打开作品');
  return {topic: match[1], comic: match[2], episode: match[3], api: '/api/comic/' + match[2] + (chapter ? '/episode/' + match[3] : '')};
}
function thDate(seconds) {
  if (seconds == null) return null;
  if (typeof seconds !== 'number' || !Number.isFinite(seconds) || seconds < 0 || seconds > 253402300799) thFail('章节日期格式无效');
  return new Date(seconds * 1000).toISOString();
}
async function detail(url) {
  var location = thLocation(url, false);
  var comic = thObject(await thFetch(location.api), '作品详情');
  if (comic.cid !== location.comic) thFail('作品详情编号不匹配');
  var rows = thList(comic.episodes, '章节目录', 2000);
  var seen = {};
  // Official API returns latest first. Reverse once for oldest-to-newest
  // reading, retaining all interleaved extras, notices and preview episodes.
  var chapters = rows.map(function (episode, index) {
    thObject(episode, '章节');
    var cid = thId(episode.cid);
    if (seen[cid]) thFail('章节目录含重复编号');
    seen[cid] = true;
    if (!Number.isInteger(episode.type) || episode.type < 1 || episode.type > 4) thFail('未知的章节类型');
    var title = thText(episode.title, '章节标题');
    var shortTitle = typeof episode.shortTitle === 'string' ? episode.shortTitle.trim() : '';
    var prefix = episode.type === 1 ? shortTitle : ['', '', '番外', '贺图', '公告'][episode.type];
    return {remoteId: location.topic + '/' + location.comic + '/' + cid,
      title: (prefix ? prefix + ' ' : '') + title,
      url: TH_BASE + '/' + location.topic + '/comic/' + location.comic + '/episode/' + cid,
      volumeTitle: ['','正篇','番外','贺图','公告'][episode.type],
      releaseDate: thDate(episode.displayTime != null ? episode.displayTime : index === 0 ? comic.updateTime : null)};
  }).reverse();
  return {item: thItem(comic, location.topic, false), chapters: chapters};
}
async function content(url) {
  var location = thLocation(url, true);
  var stamp = String(Date.now()) + '-' + String(++thSequence);
  var episode = thObject(await thFetch(location.api + '?_=' + stamp, true), '章节详情');
  if (episode.cid != null && episode.cid !== location.episode) thFail('章节详情编号不匹配');
  var pages = thList(episode.pageInfos, '漫画页信息', 1000);
  if (!pages.length) thFail('章节没有公开漫画页；请在官网检查访问权限');
  pages.forEach(function (page) { thObject(page, '漫画页信息'); });
  var images = new Array(pages.length);
  var cursor = 0;
  var failure = null;
  async function worker() {
    while (!failure && cursor < pages.length) {
      var index = cursor++;
      try {
        var page = thObject(await thFetch(location.api + '/page?pageNum=' + (index + 1) + '&_=' + stamp, true), '漫画页');
        if (page.pageNum != null && page.pageNum !== index + 1) thFail('漫画页码不匹配');
        images[index] = thImage(page.url);
      } catch (error) { failure = error; }
    }
  }
  var workers = [];
  for (var i = 0; i < Math.min(4, pages.length); i++) workers.push(worker());
  await Promise.all(workers);
  if (failure) throw failure;
  return {images: images};
}
